package com.cena.customer
import android.app.*;import android.animation.ValueAnimator;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.net.*;import java.util.concurrent.Executors
class MainActivity:Activity(){private val bg=Color.rgb(250,246,243);private val wine=Color.rgb(93,16,10);private val ex=Executors.newSingleThreadExecutor();private lateinit var body:LinearLayout;private val pref by lazy{getSharedPreferences("cena",0)};private var restaurant:JSONObject?=null;private var meal:JSONObject?=null;private var slot:JSONObject?=null;private var qty=1;private val mainHandler=Handler(Looper.getMainLooper());private val countdownTasks=mutableListOf<Runnable>()
 override fun onCreate(b:Bundle?){super.onCreate(b);window.statusBarColor=bg;window.navigationBarColor=bg;window.decorView.systemUiVisibility=View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR;home()}
 private fun base(){countdownTasks.forEach{mainHandler.removeCallbacks(it)};countdownTasks.clear();val sc=ScrollView(this);val outer=LinearLayout(this).apply{orientation=1;gravity=Gravity.CENTER_HORIZONTAL;setBackgroundColor(bg)};body=LinearLayout(this).apply{orientation=1;setPadding(22,18,22,24);layoutParams=LinearLayout.LayoutParams(-1,-2).apply{width=resources.displayMetrics.widthPixels.coerceAtMost((600*resources.displayMetrics.density).toInt())}};outer.addView(body);sc.addView(outer);setContentView(sc);if(ValueAnimator.areAnimatorsEnabled()){body.alpha=0f;body.translationY=10f;body.animate().alpha(1f).translationY(0f).setDuration(240).start()}}
 private fun title(s:String,z:Float=25f){body.addView(TextView(this).apply{text=s;textSize=z;setTextColor(wine);setPadding(0,9,0,8);typeface=android.graphics.Typeface.DEFAULT_BOLD})};private fun text(s:String){body.addView(TextView(this).apply{text=s;textSize=15f;setTextColor(Color.DKGRAY);setPadding(0,5,0,10)})};private fun button(s:String,f:()->Unit){body.addView(Button(this).apply{text=s;setTextColor(-1);background=GradientDrawable().apply{setColor(wine);cornerRadius=(16f+((390f-resources.displayMetrics.widthPixels/resources.displayMetrics.density)/110f*10f)).coerceIn(16f,26f)*resources.displayMetrics.density};setOnClickListener{f()}})};private fun field(s:String):EditText{val e=EditText(this).apply{hint=s};body.addView(e);return e}
 private fun go(task:()->String,done:(String)->Unit){ex.execute{try{val x=task();runOnUiThread{done(x)}}catch(e:Exception){runOnUiThread{Toast.makeText(this,e.message?:"Request failed",Toast.LENGTH_LONG).show()}}}}
 private fun req(path:String,method:String="GET",data:JSONObject?=null):String{val c=URL(BuildConfig.SUPABASE_URL.trimEnd('/')+path).openConnection() as HttpURLConnection;c.requestMethod=method;c.connectTimeout=9000;c.readTimeout=12000;c.setRequestProperty("apikey",BuildConfig.SUPABASE_KEY);c.setRequestProperty("Authorization","Bearer "+(pref.getString("token",BuildConfig.SUPABASE_KEY)?:BuildConfig.SUPABASE_KEY));c.setRequestProperty("Content-Type","application/json");if(data!=null){c.doOutput=true;c.outputStream.use{it.write(data.toString().toByteArray())}};val st=if(c.responseCode<400)c.inputStream else c.errorStream;val out=st.bufferedReader().readText();if(c.responseCode>=400)throw Exception(out);return out}
 private fun imageResource(key:String):Int { val safe=key.lowercase().replace("-","_");val found=resources.getIdentifier(safe,"drawable",packageName);if(found!=0)return found;return when(safe){"sunrise_cafe_cover"->R.drawable.tacos;"little_fig_cover"->R.drawable.mediterranean;else->R.drawable.mediterranean} }
 private fun home(){base();title("cena",32f);text("Good food, slower hours. Reserve local meal kits for pickup.");body.addView(TextView(this).apply{text="⌖   LOCAL PICKUP  ·  NEAR YOU\n\n  ─────── 🍽 ───────\n    ╲      ╱    ╲\n  🍲 ──────── 🌿";textSize=19f;setTextColor(wine);setPadding(18,28,18,28);setBackgroundColor(Color.rgb(239,228,218));setOnClickListener{startActivity(Intent(Intent.ACTION_VIEW,Uri.parse("geo:37.7749,-122.4194?q=meal+kit+pickup")))}});text("Discover neighborhood kitchens and their next available pickup times.");button("Explore kitchens"){catalog()};button("Sign in with email code"){auth()};button("My reservations"){if(pref.getString("token",null)==null)auth()else orders()};text("Same-day or scheduled pickup · Pay at the restaurant")}
 private fun auth(){base();title("Your Cena account");text("We'll email you a one-time sign-in code.");val e=field("Email address");val c=field("6-digit code");button("Send code"){go({req("/auth/v1/otp","POST",JSONObject().put("email",e.text.toString().trim()).put("create_user",true))}){Toast.makeText(this,"Check your email",Toast.LENGTH_LONG).show()}};button("Verify code"){go({req("/auth/v1/verify","POST",JSONObject().put("email",e.text.toString().trim()).put("token",c.text.toString().trim()).put("type","email"))}){val j=JSONObject(it);pref.edit().putString("token",j.optString("access_token")).apply();catalog()}};button("Back"){home()}}
 private fun catalog(){if(BuildConfig.SUPABASE_URL.isBlank()){base();title("Kitchens nearby");text("Set SUPABASE_URL and SUPABASE_KEY in gradle.properties to connect live kitchens, menus, pickup times and reservations.");button("Back"){home()};return};go({req("/rest/v1/restaurants?select=id,name,cuisine,address,image_key,curbside_enabled&active=eq.true&order=name")}){val a=JSONArray(it);base();title("Kitchens nearby");if(a.length()==0)text("No kitchens available right now.");val rail=HorizontalScrollView(this).apply{isHorizontalScrollBarEnabled=false};val cards=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};rail.addView(cards);body.addView(rail);for(i in 0 until a.length()){val r=a.getJSONObject(i);val card=LinearLayout(this).apply{orientation=1;setPadding(0,0,14,10);layoutParams=LinearLayout.LayoutParams((250*resources.displayMetrics.density).toInt(),-2)};val photo=ImageView(this).apply{layoutParams=LinearLayout.LayoutParams(-1,(142*resources.displayMetrics.density).toInt());scaleType=ImageView.ScaleType.CENTER_CROP;setImageResource(imageResource(r.optString("image_key","mediterranean")))};card.addView(photo);card.addView(TextView(this).apply{text="${r.optString("name")} · ${r.optString("cuisine")}\n${r.optString("address")}";textSize=16f;setTextColor(wine);setPadding(8,8,8,6);typeface=android.graphics.Typeface.DEFAULT_BOLD});card.setOnClickListener{restaurant=r;menu()};cards.addView(card)};button("Back"){home()}}}
 private fun menu(){val r=restaurant!!;go({req("/rest/v1/catalog_items?select=id,name,description,price_cents,image_key&restaurant_id=eq.${r.getString("id")}&active=eq.true&published_at=not.is.null&order=name")}){val a=JSONArray(it);base();title(r.optString("name"));text(r.optString("address"));for(i in 0 until a.length()){val m=a.getJSONObject(i);val photo=ImageView(this).apply{layoutParams=LinearLayout.LayoutParams(-1,(190*resources.displayMetrics.density).toInt());scaleType=ImageView.ScaleType.CENTER_CROP;setImageResource(imageResource(m.optString("image_key","mediterranean")))};body.addView(photo);button("${m.optString("name")}  ·  $${"%.2f".format(m.optInt("price_cents")/100.0)}\n${m.optString("description")}"){meal=m;qty=1;loadSlots()}};button("Back to kitchens"){catalog()}}}
 private fun loadSlots(){val r=restaurant!!;go({req("/rest/v1/pickup_slots?select=id,starts_at,ends_at,cutoff_at&restaurant_id=eq.${r.getString("id")}&active=eq.true&starts_at=gt.${java.time.Instant.now()}&cutoff_at=gt.${java.time.Instant.now()}&order=starts_at")}){val a=JSONArray(it);base();title("Choose pickup day");if(a.length()==0)text("No pickup windows remain. Check again later.");val days=(0 until a.length()).map{a.getJSONObject(it).optString("starts_at").take(10)}.distinct();for(day in days)button(java.time.LocalDate.parse(day).let{it.dayOfWeek.name.lowercase().replaceFirstChar(Char::uppercase)+", "+it.month.name.lowercase().replaceFirstChar(Char::uppercase)+" "+it.dayOfMonth}){showTimes(day,a)};button("Back to menu"){menu()}}}
private fun showTimes(day:String,a:JSONArray){base();title(java.time.LocalDate.parse(day).let{it.dayOfWeek.name.lowercase().replaceFirstChar(Char::uppercase)+", "+it.month.name.lowercase().replaceFirstChar(Char::uppercase)+" "+it.dayOfMonth});for(i in 0 until a.length()){val sl=a.getJSONObject(i);if(!sl.optString("starts_at").startsWith(day))continue;val cutoff=java.time.Instant.parse(sl.optString("cutoff_at")).toEpochMilli();val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(12,10,12,10);background=GradientDrawable().apply{setColor(Color.WHITE);cornerRadius=14*resources.displayMetrics.density};layoutParams=LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=(10*resources.displayMetrics.density).toInt()}};row.addView(TextView(this).apply{text=sl.optString("starts_at").substring(11,16);textSize=19f;setTextColor(wine);typeface=android.graphics.Typeface.DEFAULT_BOLD;layoutParams=LinearLayout.LayoutParams(0,-2,1f)});val badge=TextView(this).apply{setTextColor(Color.rgb(28,112,61));textSize=13f;setPadding(10,7,10,7);background=GradientDrawable().apply{setColor(Color.rgb(239,249,240));cornerRadius=12*resources.displayMetrics.density;setStroke((1*resources.displayMetrics.density).toInt(),Color.rgb(53,142,83))}};row.addView(badge);val tick=object:Runnable{override fun run(){val left=(cutoff-System.currentTimeMillis()).coerceAtLeast(0);val sec=left/1000;badge.text=if(sec>=3600)"${sec/3600}h ${(sec%3600)/60}m to cutoff" else "${sec/60}m ${sec%60}s to cutoff";row.isEnabled=left>0;badge.alpha=if(left>0)1f else .55f;if(left>0)mainHandler.postDelayed(this,1000)}};countdownTasks.add(tick);tick.run();row.setOnClickListener{slot=sl;checkout()};body.addView(row)};button("Choose another day"){loadSlots()}} private fun checkout(){base();title("Reserve your kit");text(meal?.optString("name")?:"");text("Quantity: $qty");val curb=CheckBox(this).apply{text="Curbside pickup";setTextColor(wine)};body.addView(curb);val brand=field("Vehicle make");val color=field("Vehicle color");val model=field("Vehicle model");listOf(brand,model,color).forEach{it.visibility=View.GONE};curb.setOnCheckedChangeListener{_,checked->listOf(brand,model,color).forEach{it.visibility=if(checked)View.VISIBLE else View.GONE}};button("Add one more"){qty++;checkout()};button("Reserve · pay at pickup"){if(pref.getString("token",null)==null){auth();Toast.makeText(this,"Sign in to reserve",Toast.LENGTH_SHORT).show()}else go({val vehicle=if(curb.isChecked)JSONObject().put("make",brand.text.toString()).put("model",model.text.toString()).put("color",color.text.toString())else JSONObject();val p=JSONObject().put("p_restaurant_id",restaurant!!.getString("id")).put("p_slot_id",slot!!.getString("id")).put("p_idempotency_key",java.util.UUID.randomUUID().toString()).put("p_pickup_mode",if(curb.isChecked)"curbside" else "counter").put("p_vehicle",vehicle).put("p_items",JSONArray().put(JSONObject().put("item_id",meal!!.getString("id")).put("quantity",qty)));req("/rest/v1/rpc/create_order","POST",p)}){Toast.makeText(this,"Reservation confirmed",Toast.LENGTH_LONG).show();home()}};button("Back to times"){loadSlots()}} private fun orders(){go({req("/rest/v1/orders?select=id,status,subtotal_cents,pickup_starts_at,restaurants(name)&order=created_at.desc&limit=20")}){val a=JSONArray(it);base();title("My reservations");if(a.length()==0)text("No reservations yet.");for(i in 0 until a.length()){val o=a.getJSONObject(i);text("${o.optJSONObject("restaurants")?.optString("name")} · ${o.optString("status")}\n${o.optString("pickup_starts_at").replace("T"," · ").take(17)}")};button("Back"){home()}}}
}
